import ast
import os
import subprocess
import sys
import tempfile
import time
import tomllib
import unittest
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Tuple, Iterable

# Constants
SKIPPED = 'skipped'
PASSED = 'passed'
FAILED = 'failed'
DEFAULT_PENALTY_PER_GATE = 6.25
DEFAULT_TIMEOUT_S = 60

# Dependency contract: hae/evaluation/artifacts.py
# Since this is being implemented in parallel, we assume the functions exist.
# If they don't, we provide a minimal fallback to ensure the module loads,
# but the spec implies they are available.
try:
    from hae.evaluation.artifacts import (
        filter_bundle,
        is_generated_path,
        is_malformed_path,
        sanitize_path,
        partition_bundle,
        count_source_files
    )
except ImportError:
    # Fallback implementation if artifacts.py is not yet available in the environment
    # This ensures the harness can still run its logic, though it might miss
    # specific artifact filtering rules if the real module is stricter.
    EXCLUDED_DIR_SEGMENTS = ('.pytest_cache', '__pycache__', 'venv', '.venv', '.git', '.mypy_cache', '.ruff_cache', '.tox', 'node_modules', '.ipynb_checkpoints')
    EXCLUDED_DIR_SUFFIXES = ('.egg-info', '.dist-info')

    def is_generated_path(path: str) -> bool:
        parts = path.replace('\\', '/').split('/')
        for part in parts:
            if part in EXCLUDED_DIR_SEGMENTS:
                return True
            if any(part.endswith(s) for s in EXCLUDED_DIR_SUFFIXES):
                return True
        return False

    def is_malformed_path(path: str) -> bool:
        if not path:
            return True
        if path != path.strip():
            return True
        if '*' in path or '`' in path:
            return True
        if path.startswith('-'):
            return True
        if path.endswith('.') or path.endswith('~'):
            return True
        return False

    def sanitize_path(path: str) -> str:
        path = path.strip()
        path = path.replace('*', '').replace('`', '')
        if path.startswith('-'):
            path = path[1:]
        if path.endswith('.') or path.endswith('~'):
            path = path[:-1]
        return path

    def filter_bundle(bundle: Dict[str, str]) -> Dict[str, str]:
        return {k: v for k, v in bundle.items() if not is_generated_path(k) and not is_malformed_path(k)}

    def partition_bundle(bundle: Dict[str, str]) -> Tuple[Dict[str, str], Dict[str, str], Dict[str, str]]:
        authored = {}
        generated = {}
        malformed = {}
        for k, v in bundle.items():
            if is_generated_path(k):
                generated[k] = v
            elif is_malformed_path(k):
                malformed[k] = v
            else:
                authored[k] = v
        return authored, generated, malformed

    def count_source_files(bundle: Dict[str, str], suffixes: Iterable[str] = ('.py',)) -> int:
        count = 0
        for path in bundle:
            if any(path.endswith(s) for s in suffixes):
                count += 1
        return count


@dataclass
class GateResult:
    """Outcome of a single verification gate."""
    name: str
    status: str
    method: str
    detail: str = ''
    duration_s: float = 0.0
    evidence: Dict[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == PASSED

    @property
    def evaluated(self) -> bool:
        return self.status != SKIPPED


@dataclass
class VerificationReport:
    """Aggregate result across all gates."""
    gates: List[GateResult]
    score_penalty: float
    authored_files: int
    python_files: int
    source: str = 'bundle'
    harness_version: str = '3.0-execution'

    def gate(self, name: str) -> Optional[GateResult]:
        for g in self.gates:
            if g.name == name:
                return g
        return None

    @property
    def evaluated_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.evaluated]

    @property
    def passed_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.passed]

    @property
    def gate_status(self) -> Dict[str, str]:
        """Gate name -> PASSED | FAILED | SKIPPED. The fitness function's input."""
        return {g.name: g.status for g in self.gates}

    @property
    def gate_detail(self) -> Dict[str, str]:
        return {g.name: g.detail for g in self.gates}

    @property
    def pass_rate(self) -> float:
        """Fraction of *evaluated* gates that passed. Skips are excluded."""
        evaluated = self.evaluated_gates
        if not evaluated:
            return 0.0
        passed_count = len([g for g in evaluated if g.passed])
        return passed_count / len(evaluated)

    def summary(self) -> str:
        lines = [f"Verification Report ({self.source})"]
        lines.append(f"Authored Files: {self.authored_files} (Python: {self.python_files})")
        lines.append(f"Score Penalty: {self.score_penalty:.2f}")
        lines.append("-" * 40)
        for g in self.gates:
            status_icon = "✓" if g.passed else ("✗" if g.status == FAILED else "-")
            lines.append(f"[{status_icon}] {g.name}: {g.status} ({g.method})")
            if g.detail:
                lines.append(f"    Detail: {g.detail}")
        return "\n".join(lines)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "gates": [
                {
                    "name": g.name,
                    "status": g.status,
                    "method": g.method,
                    "detail": g.detail,
                    "duration_s": g.duration_s,
                    "evidence": g.evidence
                }
                for g in self.gates
            ],
            "score_penalty": self.score_penalty,
            "authored_files": self.authored_files,
            "python_files": self.python_files,
            "source": self.source,
            "harness_version": self.harness_version,
            "gate_status": self.gate_status,
            "pass_rate": self.pass_rate
        }


def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    blocks = {}
    lines = text.splitlines()
    in_block = False
    current_path = None
    current_content = []

    # Simple regex-free parser for ```path\ncontent\n```
    # We look for lines starting with ```
    for line in lines:
        stripped = line.strip()
        if stripped.startswith("```"):
            if in_block:
                # End of block
                if current_path:
                    blocks[current_path] = "\n".join(current_content)
                in_block = False
                current_path = None
                current_content = []
            else:
                # Start of block
                in_block = True
                # Try to extract path from the fence line
                # Format: ```path/to/file.py
                # Or just ```
                fence_content = stripped[3:].strip()
                if fence_content:
                    # Heuristic: if it looks like a path, use it. 
                    # Otherwise, we might need to look at the next line or ignore.
                    # The spec says "path->content map". Usually the fence info string is the path.
                    current_path = fence_content
                else:
                    current_path = None # Will need to guess or skip
        elif in_block:
            current_content.append(line)

    return blocks


class ExecutionHarness:
    """Materializes a workspace bundle and verifies it by actually running it."""

    def __init__(self, timeout_s: int = DEFAULT_TIMEOUT_S, penalty_per_gate: float = DEFAULT_PENALTY_PER_GATE, python_executable: Optional[str] = None):
        self.timeout_s = timeout_s
        self.penalty_per_gate = penalty_per_gate
        self.python_executable = python_executable or sys.executable

    def verify_workspace(self, workspace: Any = None, deliverable_text: str = '') -> VerificationReport:
        """Verifies whatever code a firm actually produced.

        This is the entry point tournaments use. A firm normally writes into a
        live `AgentWorkspace`; if it never did, we fall back to the fenced code
        blocks embedded in its written deliverable.

        `deliverable_text` is *only* mined for code blocks. Its prose is never
        passed to a gate, because the entire point of this harness is that an
        essay about OpenTelemetry cannot satisfy the telemetry gate.
        """
        bundle = {}
        source = 'bundle'

        # Try to get bundle from workspace object
        if workspace is not None:
            # Assume workspace has a method to get files or is a dict
            if hasattr(workspace, 'get_files'):
                bundle = workspace.get_files()
                source = 'workspace'
            elif isinstance(workspace, dict):
                bundle = workspace
                source = 'workspace'
            elif hasattr(workspace, 'files'):
                bundle = workspace.files
                source = 'workspace'

        # Fallback to deliverable text if bundle is empty
        if not bundle and deliverable_text:
            bundle = extract_code_blocks(deliverable_text)
            source = 'deliverable'

        return self.verify_bundle(bundle, source=source)

    def verify_bundle(self, bundle: Dict[str, str], source: str = 'bundle') -> VerificationReport:
        """Verifies an in-memory path->content map by writing it to a temp dir."""
        # Filter bundle to remove generated/malformed files
        authored_bundle = filter_bundle(bundle)

        # Count files
        authored_files = len(authored_bundle)
        python_files = count_source_files(authored_bundle, suffixes=('.py',))

        if not authored_bundle:
            # Empty workspace
            gates = [
                GateResult(name='syntax', status=FAILED, method='ast', detail='No authored files'),
                GateResult(name='build', status=FAILED, method='metadata', detail='No authored files'),
                GateResult(name='smoke', status=FAILED, method='import', detail='No authored files'),
                GateResult(name='tests', status=FAILED, method='pytest', detail='No authored files'),
                GateResult(name='telemetry', status=FAILED, method='ast', detail='No authored files'),
            ]
            failed_count = sum(1 for g in gates if g.status == FAILED)
            return VerificationReport(
                gates=gates,
                score_penalty=failed_count * self.penalty_per_gate,
                authored_files=0,
                python_files=0,
                source=source
            )

        with tempfile.TemporaryDirectory() as tmpdir:
            # Write files to temp dir
            for path, content in authored_bundle.items():
                full_path = os.path.join(tmpdir, path)
                os.makedirs(os.path.dirname(full_path), exist_ok=True)
                with open(full_path, 'w', encoding='utf-8') as f:
                    f.write(content)

            return self.verify_directory(tmpdir, authored=authored_bundle, source=source)

    def verify_directory(self, workdir: str, authored: Optional[Dict[str, str]] = None, source: str = 'directory') -> VerificationReport:
        """Verifies an existing workspace directory."""
        if authored is None:
            # Scan directory
            authored = {}
            for root, dirs, files in os.walk(workdir):
                # Prune excluded dirs
                dirs[:] = [d for d in dirs if not is_generated_path(os.path.relpath(os.path.join(root, d), workdir))]
                for file in files:
                    rel_path = os.path.relpath(os.path.join(root, file), workdir)
                    if not is_generated_path(rel_path) and not is_malformed_path(rel_path):
                        try:
                            with open(os.path.join(root, file), 'r', encoding='utf-8') as f:
                                authored[rel_path] = f.read()
                        except Exception:
                            pass

        authored_files = len(authored)
        python_files = count_source_files(authored, suffixes=('.py',))

        gates = []

        # 1. Syntax Gate
        gates.append(self._gate_syntax(workdir, authored))

        # 2. Build Gate
        gates.append(self._gate_build(workdir, authored))

        # 3. Smoke Gate
        gates.append(self._gate_smoke(workdir, authored))

        # 4. Tests Gate
        gates.append(self._gate_tests(workdir, authored))

        # 5. Telemetry Gate
        gates.append(self._gate_telemetry(workdir, authored))

        failed_count = sum(1 for g in gates if g.status == FAILED)
        score_penalty = failed_count * self.penalty_per_gate

        return VerificationReport(
            gates=gates,
            score_penalty=score_penalty,
            authored_files=authored_files,
            python_files=python_files,
            source=source
        )

    def _gate_syntax(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()
        py_files = [p for p in authored if p.endswith('.py')]

        if not py_files:
            return GateResult(
                name='syntax',
                status=FAILED,
                method='ast',
                detail='No Python files found',
                duration_s=time.time() - start
            )

        errors = []
        for path in py_files:
            content = authored[path]
            try:
                ast.parse(content)
            except SyntaxError as e:
                errors.append(f"{path}: {e}")

        duration = time.time() - start
        if errors:
            return GateResult(
                name='syntax',
                status=FAILED,
                method='ast',
                detail='Syntax errors: ' + '; '.join(errors),
                duration_s=duration
            )

        return GateResult(
            name='syntax',
            status=PASSED,
            method='ast',
            detail=f"All {len(py_files)} Python files parsed successfully",
            duration_s=duration
        )

    def _gate_build(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Check for metadata files
        metadata_files = ['pyproject.toml', 'setup.py', 'setup.cfg']
        found_metadata = None
        for mf in metadata_files:
            if mf in authored:
                found_metadata = mf
                break

        if not found_metadata:
            return GateResult(
                name='build',
                status=FAILED,
                method='metadata',
                detail='No packaging metadata found (pyproject.toml, setup.py, setup.cfg)',
                duration_s=time.time() - start
            )

        # Validate pyproject.toml if present
        if 'pyproject.toml' in authored:
            try:
                data = tomllib.loads(authored['pyproject.toml'])
                # Must contain at least one of [project], [build-system], or [tool]
                if not any(k in data for k in ['project', 'build-system', 'tool']):
                    return GateResult(
                        name='build',
                        status=FAILED,
                        method='metadata',
                        detail='pyproject.toml is valid TOML but missing required tables ([project], [build-system], [tool])',
                        duration_s=time.time() - start
                    )
            except Exception as e:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method='metadata',
                    detail=f'pyproject.toml is malformed: {e}',
                    duration_s=time.time() - start
                )

        # Try pip install
        # Check if pip is available
        try:
            subprocess.run(
                [self.python_executable, '-m', 'pip', '--version'],
                capture_output=True,
                timeout=10
            )
        except Exception:
            return GateResult(
                name='build',
                status=SKIPPED,
                method='pip',
                detail='pip not available',
                duration_s=time.time() - start
            )

        try:
            # Run pip install -e . --no-deps --no-build-isolation
            result = subprocess.run(
                [self.python_executable, '-m', 'pip', 'install', '-e', '.', '--no-deps', '--no-build-isolation'],
                cwd=workdir,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )
            duration = time.time() - start
            if result.returncode == 0:
                return GateResult(
                    name='build',
                    status=PASSED,
                    method='pip',
                    detail='Package installed successfully',
                    duration_s=duration
                )
            else:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method='pip',
                    detail=f'pip install failed: {result.stderr}',
                    duration_s=duration
                )
        except subprocess.TimeoutExpired:
            return GateResult(
                name='build',
                status=FAILED,
                method='pip',
                detail='pip install timed out',
                duration_s=time.time() - start
            )
        except Exception as e:
            return GateResult(
                name='build',
                status=FAILED,
                method='pip',
                detail=f'pip install error: {e}',
                duration_s=time.time() - start
            )

    def _gate_smoke(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Find non-test authored modules
        # Exclude test files
        test_files = [p for p in authored if 'test' in os.path.basename(p).lower()]
        non_test_modules = []

        for path in authored:
            if not path.endswith('.py'):
                continue
            if path in test_files:
                continue
            # Convert path to module name
            # Remove .py
            mod_path = path[:-3]
            # Replace / with .
            mod_name = mod_path.replace('/', '.').replace('\\', '.')
            # Handle __init__.py -> package name
            if mod_name.endswith('.__init__'):
                mod_name = mod_name[:-9]
            if mod_name:
                non_test_modules.append(mod_name)

        if not non_test_modules:
            return GateResult(
                name='smoke',
                status=FAILED,
                method='import',
                detail='No importable non-test modules found',
                duration_s=time.time() - start
            )

        # Prepare PYTHONPATH
        src_dir = os.path.join(workdir, 'src')
        python_path = f"{workdir}:{src_dir}"
        env = os.environ.copy()
        env['PYTHONPATH'] = python_path

        # Try importing each module in a subprocess
        # We do this one by one to isolate failures
        import_errors = []
        module_not_found_errors = []

        for mod_name in non_test_modules:
            try:
                # Use a simple script to import
                script = f"import {mod_name}"
                result = subprocess.run(
                    [self.python_executable, '-c', script],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )
                if result.returncode != 0:
                    stderr = result.stderr
                    if 'ModuleNotFoundError' in stderr:
                        # Check if it's a third-party package
                        # If the module itself is not found, it's a failure.
                        # If a dependency is not found, it's skipped.
                        # This is tricky. If `import mymodule` fails with ModuleNotFoundError: No module named 'mymodule', it's a failure.
                        # If it fails with ModuleNotFoundError: No module named 'opentelemetry', it's skipped.
                        # We can check if the module name is in the error.
                        if f"No module named '{mod_name}'" in stderr or f"No module named \"{mod_name}\"" in stderr:
                            import_errors.append(f"{mod_name}: Module not found")
                        else:
                            module_not_found_errors.append(f"{mod_name}: Dependency missing")
                    else:
                        import_errors.append(f"{mod_name}: {stderr.strip()}")
            except Exception as e:
                import_errors.append(f"{mod_name}: {e}")

        duration = time.time() - start

        if import_errors:
            return GateResult(
                name='smoke',
                status=FAILED,
                method='import',
                detail='Import errors: ' + '; '.join(import_errors),
                duration_s=duration
            )

        if module_not_found_errors:
            return GateResult(
                name='smoke',
                status=SKIPPED,
                method='import',
                detail='Skipped due to missing third-party dependencies: ' + '; '.join(module_not_found_errors),
                duration_s=duration
            )

        return GateResult(
            name='smoke',
            status=PASSED,
            method='import',
            detail=f"All {len(non_test_modules)} modules imported successfully",
            duration_s=duration
        )

    def _gate_tests(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Discover test files
        test_files = [p for p in authored if 'test' in os.path.basename(p).lower() and p.endswith('.py')]

        if not test_files:
            return GateResult(
                name='tests',
                status=FAILED,
                method='pytest',
                detail='No test files found',
                duration_s=time.time() - start
            )

        # Prepare PYTHONPATH
        src_dir = os.path.join(workdir, 'src')
        # Ensure workdir and src are on PYTHONPATH for subprocess imports
        existing_pythonpath = os.environ.get('PYTHONPATH', '')
        if existing_pythonpath:
            python_path = f'{workdir}:{src_dir}:{existing_pythonpath}'
        else:
            python_path = f'{workdir}:{src_dir}'
        env = os.environ.copy()
        env['PYTHONPATH'] = python_path

        # Check if pytest is installed
        try:
            subprocess.run(
                [self.python_executable, '-m', 'pytest', '--version'],
                capture_output=True,
                timeout=10
            )
            has_pytest = True
        except Exception:
            has_pytest = False

        if has_pytest:
            # Run pytest
            try:
                result = subprocess.run(
                    [self.python_executable, '-m', 'pytest', '-v', '--tb=short'],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )
                duration = time.time() - start
                if result.returncode == 0:
                    return GateResult(
                        name='tests',
                        status=PASSED,
                        method='pytest',
                        detail='All tests passed',
                        duration_s=duration
                    )
                else:
                    # Check if it failed due to ModuleNotFoundError
                    if 'ModuleNotFoundError' in result.stderr or 'ModuleNotFoundError' in result.stdout:
                        # Check if it's a third-party package
                        # If the test file itself imports a missing package, it's skipped.
                        # If the test fails, it's failed.
                        # Pytest usually reports collection errors.
                        if 'ERROR' in result.stdout and 'ModuleNotFoundError' in result.stdout:
                             return GateResult(
                                name='tests',
                                status=SKIPPED,
                                method='pytest',
                                detail='Tests skipped due to missing dependencies',
                                duration_s=duration
                            )
                    return GateResult(
                        name='tests',
                        status=FAILED,
                        method='pytest',
                        detail=f'Tests failed: {result.stdout[-500:]}',
                        duration_s=duration
                    )
            except subprocess.TimeoutExpired:
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='pytest',
                    detail='Tests timed out',
                    duration_s=time.time() - start
                )
            except Exception as e:
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='pytest',
                    detail=f'Pytest error: {e}',
                    duration_s=time.time() - start
                )
        else:
            # Stdlib fallback
            # Run a script that imports each test file and collects/executes tests
            # We need to handle both bare def test_*() and unittest.TestCase

            # Create a runner script
            runner_script = '''
import sys
import os
