import importlib.util
import inspect

def run_tests(test_files):
    collected_tests = 0
    failures = []

    for test_file in test_files:
        try:
            # Load module
            spec = importlib.util.spec_from_file_location("test_module", test_file)
            if spec is None or spec.loader is None:
                continue
            module = importlib.util.module_from_spec(spec)
            sys.modules["test_module"] = module
            spec.loader.exec_module(module)

            # Find bare test functions
            for name in dir(module):
                if name.startswith('test_'):
                    func = getattr(module, name)
                    if callable(func) and not isinstance(func, type):
                        try:
                            sig = inspect.signature(func)
                            if len(sig.parameters) == 0:
                                collected_tests += 1
                                func()
                        except Exception as e:
                            failures.append(f"{test_file}::{name}: {e}")

            # Find unittest.TestCase subclasses
            for name in dir(module):
                obj = getattr(module, name)
                if isinstance(obj, type) and issubclass(obj, unittest.TestCase) and obj is not unittest.TestCase:
                    # Run tests in this class
                    suite = unittest.TestLoader().loadTestsFromTestCase(obj)
                    runner = unittest.TextTestRunner(verbosity=0)
                    result = runner.run(suite)
                    collected_tests += result.testsRun
                    if result.failures or result.errors:
                        for test, tb in result.failures + result.errors:
                            failures.append(f"{test_file}::{test.id()}: {tb}")

        except ModuleNotFoundError as e:
            # If the test file itself can't be imported due to missing deps, skip
            print(f"SKIP:{test_file}:{e}")
            continue
        except Exception as e:
            failures.append(f"{test_file}: Import error: {e}")

    if failures:
        print("FAILURES:")
        for f in failures:
            print(f)
        sys.exit(1)
    elif collected_tests == 0:
        print("NO_TESTS_COLLECTED")
        sys.exit(0)
    else:
        print(f"OK: {collected_tests} tests passed")
        sys.exit(0)

if __name__ == '__main__':
    test_files = sys.argv[1:]
    run_tests(test_files)
'''
            try:
                # Write runner script to temp file
                runner_path = os.path.join(workdir, '_test_runner.py')
                with open(runner_path, 'w') as f:
                    f.write(runner_script)

                # Run it
                abs_test_files = [os.path.abspath(os.path.join(workdir, p)) for p in test_files]
                result = subprocess.run(
                    [self.python_executable, runner_path] + abs_test_files,
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )
                duration = time.time() - start

                # Clean up
                try:
                    os.remove(runner_path)
                except:
                    pass

                if result.returncode == 0:
                    if 'SKIP:' in result.stdout:
                        return GateResult(
                            name='tests',
                            status=SKIPPED,
                            method='stdlib',
                            detail='Tests skipped due to missing dependencies',
                            duration_s=duration
                        )
                    return GateResult(
                        name='tests',
                        status=PASSED,
                        method='stdlib',
                        detail=result.stdout.strip(),
                        duration_s=duration
                    )
                else:
                    if 'ModuleNotFoundError' in result.stderr or 'ModuleNotFoundError' in result.stdout:
                         return GateResult(
                            name='tests',
                            status=SKIPPED,
                            method='stdlib',
                            detail='Tests skipped due to missing dependencies',
                            duration_s=duration
                        )
                    return GateResult(
                        name='tests',
                        status=FAILED,
                        method='stdlib',
                        detail=f'Tests failed: {result.stderr}',
                        duration_s=duration
                    )
            except Exception as e:
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='stdlib',
                    detail=f'Stdlib runner error: {e}',
                    duration_s=time.time() - start
                )

    def _gate_telemetry(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        py_files = [p for p in authored if p.endswith('.py')]

        if not py_files:
            return GateResult(
                name='telemetry',
                status=FAILED,
                method='ast',
                detail='No Python files found',
                duration_s=time.time() - start
            )

        has_import = False
        has_call = False

        tracer_methods = {
            'start_as_current_span',
            'start_span',
            'get_tracer',
            'get_tracer_provider',
            'set_tracer_provider',
            'get_meter'
        }

        for path in py_files:
            content = authored[path]
            try:
                tree = ast.parse(content)
            except SyntaxError:
                continue

            for node in ast.walk(tree):
                # Check for import opentelemetry or from opentelemetry ...
                if isinstance(node, ast.Import):
                    for alias in node.names:
                        if alias.name == 'opentelemetry' or alias.name.startswith('opentelemetry.'):
                            has_import = True
                elif isinstance(node, ast.ImportFrom):
                    if node.module == 'opentelemetry' or (node.module and node.module.startswith('opentelemetry.')):
                        has_import = True

                # Check for calls to tracer/span methods
                if isinstance(node, ast.Call):
                    func = node.func
                    # Handle method calls like tracer.start_span()
                    if isinstance(func, ast.Attribute):
                        if func.attr in tracer_methods:
                            has_call = True
                    # Handle function calls like get_tracer()
                    elif isinstance(func, ast.Name):
                        if func.id in tracer_methods:
                            has_call = True

        duration = time.time() - start

        if has_import and has_call:
            return GateResult(
                name='telemetry',
                status=PASSED,
                method='ast',
                detail='OpenTelemetry import and tracer/span calls found',
                duration_s=duration
            )

        if not has_import:
            return GateResult(
                name='telemetry',
                status=FAILED,
                method='ast',
                detail='No OpenTelemetry import found',
                duration_s=duration
            )

        if not has_call:
            return GateResult(
                name='telemetry',
                status=FAILED,
                method='ast',
                detail='OpenTelemetry imported but no tracer/span calls found',
                duration_s=duration
            )

        return GateResult(
            name='telemetry',
            status=FAILED,
            method='ast',
            detail='Telemetry requirements not met',
            duration_s=duration
        )
